Here is the commit message:
fixbug inserted by commit 622ef805

Here is the root cause:
The bug was likely caused by the use of pointer arrays for `new_cpu_usage` and `old_cpu_usage`, which could lead to improper memory allocation and access issues, resulting in incorrect CPU usage data being read or written. This could cause undefined behavior or crashes when the program attempts to dereference these pointers without proper initialization.

Here is the patch:

 void
 getCpuUsage(int* cpu_percent)
 {
   size_t len = 0;
   char *line = NULL;
   int i, percent;
   long int idle_time, other_time;
   char cpu_name[8]; 

-  static int **new_cpu_usage[CPU_NBR][4];
-  static int **old_cpu_usage[CPU_NBR][4];
+  static int new_cpu_usage[CPU_NBR][4];
+  static int old_cpu_usage[CPU_NBR][4];

   FILE *f;
   if(NULL == (f = fopen("/proc/stat", "r")))
     return;

   for(i = 0; i < CPU_NBR; ++i)
     {
       getline(&line,&len,f);
       sscanf(
              line, 
              "%s %d %d %d %d",
              cpu_name,
              &new_cpu_usage[i][0],
              &new_cpu_usage[i][1],
              &new_cpu_usage[i][2],
              &new_cpu_usage[i][3]
              );

       if(line != NULL)
         {
           free(line); 
           line = NULL;
         }

       idle_time = new_cpu_usage[i][3] - old_cpu_usage[i][3];
       other_time = new_cpu_usage[i][0] - old_cpu_usage[i][0]
         + new_cpu_usage[i][1] - old_cpu_usage[i][1]
         + new_cpu_usage[i][2] - old_cpu_usage[i][2];

       if(idle_time + other_time != 0)
         cpu_percent[i] = (other_time*100)/(idle_time + other_time);
       else
         cpu_percent[i] = 0; 

       old_cpu_usage[i][0] = new_cpu_usage[i][0];
       old_cpu_usage[i][1] = new_cpu_usage[i][1];
       old_cpu_usage[i][2] = new_cpu_usage[i][2];
       old_cpu_usage[i][3] = new_cpu_usage[i][3];
     }

     fclose(f);
 }



